            "During the late 1920s, the motion-picture industry underwent one of the fastest technological transformations in cultural history. Although earlier films are commonly labeled 'silent,' theater screenings were rarely quiet: live pianists, theater organists, or full orchestras accompanied nearly every major feature. What cinema lacked was reliable, prerecorded sound tightly locked to the moving lip movements and footsteps on screen. Two rival engineering solutions emerged to bridge that gap—sound-on-disc and sound-on-film—and their brief competition reshaped both movie theaters and film editing.",
            "Warner Bros. championed the sound-on-disc approach in 1926 under the trade name Vitaphone. In this system, music and dialogue were recorded onto large, sixteen-inch shellac phonograph records spinning at thirty-three and one-third revolutions per minute. Inside the projection booth, a mechanical shaft linked the turntable directly to the film projector motor so both ran together. Vitaphone delivered impressive tonal richness for its day, propelling hits like The Jazz Singer in 1927, yet it suffered from severe practical flaws in daily distribution.",
            "Whenever a 35-millimeter film reel snapped inside a busy theater, a projectionist spliced the torn ends together—removing a few frames in the process. Unfortunately, the separate phonograph disc could not be trimmed to match, leaving actors' voices permanently trailing or leading their lip movements until an alert operator manually nudged the needle forward or backward. Heavy discs also chipped or cracked during cross-country shipping, forcing small-town theaters to wait days for replacements.",
            "Sound-on-film technologies, notably Fox Movietone and RCA Photophone, solved synchronization permanently by converting audio waves into fluctuating beams of light photographed directly onto a narrow strip along the edge of the film print itself. Because picture and soundtrack shared one physical ribbon of celluloid, splicing a broken reel cut image and sound by the exact same length. Even though early optical tracks initially carried slightly more background hiss than fresh Vitaphone records, unmatched durability and editing flexibility allowed optical sound-on-film to become the universal studio standard by 1931."
