            "Every autumn, small songbirds weighing less than twenty grams set off on nighttime flights spanning entire continents. A European garden warbler or a northern wheatear may cross deserts and open seas to reach winter habitats thousands of kilometers away, often returning to the exact same tree the following spring. How do tiny brains accomplish navigation feats that rival human aviation instruments?",
            "Biologists have learned that migratory birds do not rely on a single clue; instead, they combine multiple compasses into a flexible backup system. During clear days, birds track the sun's movement across the sky, pairing that observation with an internal twenty-four-hour circadian clock so they adjust automatically as the sun shifts from east to west. After sunset, nocturnal migrants switch to a star compass, memorizing how constellations appear to rotate around a fixed celestial point—the North Star in the Northern Hemisphere.",
