            "By wrapping wire coils around the indoor room, the Wiltschkos altered the surrounding magnetic field without changing light, temperature, or landmarks. Whenever they rotated magnetic north ninety degrees eastward, the robins shifted their footprints ninety degrees eastward as well. Surprisingly, however, flipping only the horizontal north-south direction did not confuse the birds unless the vertical slope of the magnetic field changed too. That clever test revealed that birds read the downward tilt—the magnetic inclination—telling them which way leads toward the poles versus toward the equator."
