          "speaker": "f",
          "voice": "uk_f",
          "lines": [
            "Let's rewind to October 1927, when The Jazz Singer stunned theater audiences with synchronized song and brief dialogue. Everyone realized sound was the future—yet nobody agreed on which technology would survive. For roughly three years, Hollywood split between two incompatible formats: sound-on-disc and optical sound-on-film.",
            "Warner Bros. bet early on Vitaphone, which recorded sound onto oversized sixteen-inch phonograph records. And to be fair, a brand-new Vitaphone record sounded remarkably warm and clear—better, in fact, than the earliest optical soundtracks!",
            "So if Vitaphone often sounded richer in a quiet studio, why did it vanish completely by the early nineteen-thirties? The answer lies inside everyday movie theaters rather than recording studios.",
            "First, think about what happens when a physical film reel tears mid-show—which happened constantly on older projectors. A projectionist snipped out the torn sprocket holes and glued the film back together. Now that film strip is six or eight frames shorter! Wait—what happens to the separate phonograph disc spinning beside the projector? Nothing! Every single scene after that splice falls permanently out of sync unless the operator catches it and bumps the turntable needle ahead by hand.",
            "Second, shipping heavy, brittle shellac discs across snowy highways led to constant breakage—and mix-ups where reel three arrived paired with disc four! Now contrast that headache with Fox Movietone and RCA Photophone.",
            "Those systems translated sound waves into flickering light beams photographed right along the border of the celluloid film strip—just a tenth of an inch wide! Because sound and picture rode on the exact same ribbon, cutting out damaged frames trimmed sound and image identically. Once engineers reduced background hiss on optical film, studio executives abandoned fragile records almost overnight."
          ],
