        "model": "Subject: Budget Reallocation & Progress Report Extension Request — Grant #UR-206\n\nDear Dr. Okafor,\n\nI am writing to inform the committee of an unexpected supplier delay affecting my migratory songbird acoustic study. Our equipment vendor notified me yesterday that two weatherproof field microphones are back-ordered for three weeks, and expedited freight fees have increased their invoice by $280.\n\nBecause this adjustment shifts slightly more than 15% between budget categories, I am requesting formal approval to transfer $280 from my regional mileage travel line into durable equipment. My faculty advisor has confirmed I can share transport with another field team, keeping total expenditures strictly within the original $3,200 award.\n\nAdditionally, since field recording cannot begin until the sensors arrive, could I extend my spring progress report deadline from April 10 to May 1? Thank you very much for considering both requests, and please let me know if any revised spreadsheet forms are needed.\n\nSincerely,\nDevon Park\nDepartment of Biology",
        "notes": "การเก็บครบทั้ง 3 Bullets ในคำตอบ Band 6.0:\n• Bullet 1 (ย่อหน้าแรก): อธิบายชัดเจนว่าไมโครโฟนภาคสนามส่งช้า 3 สัปดาห์และค่าส่งเพิ่ม $280\n• Bullet 2 (ย่อหน้าสอง): เสนอโยกงบ $280 จากหมวดค่าเดินทางโดยแชร์รถกับทีมอื่นแทน จึงไม่เกินวงเงินเดิม $3,200 และยื่นขออนุมัติตามกฎ >15% อย่างมืออาชีพ\n• Bullet 3 (ย่อหน้าสาม): ขอขยายเวลาส่งรายงานความก้าวหน้าจาก 10 เม.ย. เป็น 1 พ.ค. อย่างสุภาพพร้อมระบุเหตุผลชัดเจน",
