      "discussion": {
        "topic": "Required Undergraduate Research vs. Applied Career Internships",
        "profPrompt": "As our university reviews its graduation requirements, the Curriculum Committee is debating whether every undergraduate should complete a mentored, independent research project (with small departmental mini-grants available) prior to graduating, or whether students should freely choose between academic research and a credit-bearing workplace internship. Which policy better prepares students for diverse careers after graduation?",
        "posts": [
          {
            "name": "Nadia",
            "text": "Requiring independent research for everyone would transform undergraduate education. Even students who never pursue a PhD gain tremendous confidence when they design a question from scratch, manage a modest budget, and defend findings with evidence. If students only take routine internships, many end up running errands rather than learning critical inquiry."
          },
          {
            "name": "Devon",
            "text": "I value research deeply, yet making it mandatory ignores how varied career paths really are. For an aspiring film editor, accountant, or social worker, spending a semester inside a real workplace teaches client communication, tight deadlines, and team workflows that solo lab projects rarely replicate. Offering funded research alongside high-quality internships respects both goals."
          }
        ],
        "model": "While Nadia rightly points out that poorly structured internships can sometimes offer shallow clerical tasks, I agree with Devon that students should choose between mentored research and a rigorous internship rather than facing a one-size-fits-all mandate. Requiring independent research across every major would strain faculty mentoring capacity: if professors suddenly had to supervise hundreds of reluctant researchers, advising quality and grant oversight would inevitably decline. Instead, the university could address Nadia's valid worry by applying clear standards to credit-bearing internships—requiring students to complete an analytical capstone portfolio or workplace problem-solving report evaluated by an advisor. That dual-track system keeps research funding focused on students eager for original inquiry while giving professionally oriented undergraduates authentic industry experience.",
        "notes": "จุดเด่นของคำตอบระดับ Band 6.0:\n• รับรู้จุดแข็งของทั้งสองฝ่าย: เห็นด้วยกับ Nadia ว่างานฝึกงานบางแห่งอาจมีแต่งานเอกสารน่าเบื่อ แต่สนับสนุนมุมมองของ Devon ในการคงไว้ทั้งสองทางเลือก\n• นำเสนอเหตุผลใหม่ที่เป็นรูปธรรม: ชี้ปัญหาทรัพยากรอาจารย์ที่ปรึกษา (strain faculty mentoring capacity) หากบังคับทุกคนทำวิจัย + เสนอวิธีคุมคุณภาพฝึกงานด้วย analytical capstone portfolio",
        "tips": "เคล็ดลับ Academic Discussion:\n• เมื่อเห็นด้วยกับฝั่งหนึ่ง แนะนำให้ 'ตอบโต้หรือแก้ข้อกังวลของอีกฝั่ง' ด้วยวิธีแก้ปัญหาเชิงระบบ จะแสดงทักษะการสังเคราะห์ความคิดที่เหนือกว่าการเลือกข้างเฉยๆ"
      }
