            "Over the last decade, coral restoration groups have planted millions of fragments onto degraded reefs, yet a troubling pattern keeps emerging: when the next marine heatwave arrives, newly planted corals often bleach at the exact same rate as wild ones.",
            "That realization pushed marine geneticists to ask a practical question: instead of propagating random survivors, can we selectively breed corals that already tolerate warmer water?",
            "This technique, known as assisted gene flow, pairs parent colonies from naturally hot lagoons or shallow back-reefs with colonies from cooler outer slopes.",
            "In controlled aquarium trials, researchers first expose hundreds of candidate fragments to brief, calibrated heat stress and measure chlorophyll retention to identify heat-resilient strains.",
            "When gametes from those warm-adapted parents cross with local corals, the resulting larvae frequently inherit elevated thermal tolerance—sometimes withstanding temperatures up to one point five degrees Celsius higher before bleaching.",
            "Of course, geneticists caution against rushing too fast: focusing narrowly on heat tolerance could inadvertently strip away resistance to coral diseases or winter cold snaps.",
            "For that reason, modern reef nurseries aim to maintain broad genetic diversity across dozens of parent genotypes rather than cloning a single 'super-coral.'",
