          "lines": [
            "When adults speak to babies, almost everyone instinctively shifts into a higher pitch, slower tempo, and exaggerated melodic contours—what linguists call infant-directed speech.",
            "For years, researchers debated whether this speech style mainly served an emotional role, soothing or engaging the child, or whether it carried measurable phonetic benefits.",
            "To test that question, acoustic phoneticians plotted the vowel spaces of mothers speaking the exact same words—such as 'bead,' 'bod,' and 'booed'—first to an adult friend and then to their six-month-old infant.",
            "Every vowel is defined acoustically by resonant frequency bands known as formants, especially the first two formants, F1 and F2, which correspond roughly to tongue height and tongue advancement.",
            "When plotted on a graph, the three corner vowels—'ee,' 'ah,' and 'oo'—form a triangle, and remarkably, the area of that vowel triangle expanded by nearly fifty percent in infant-directed speech.",
            "In other words, speakers unconsciously hyperarticulated—pushing their tongue and lips farther toward acoustic extremes so each vowel category stood sharply apart from its neighbors.",
            "Crucially, subsequent studies found that mothers who produced larger vowel triangles had infants who performed significantly better on speech-discrimination tasks months later.",
            "That link strongly suggests caregivers' acoustic exaggeration acts as a natural perceptual scaffold, making core phonetic contrasts easier for young brains to map."
          ],
