            "q": "How has talking with an academic advisor or senior mentor helped you choose courses during university?",
            "model": "Meeting with my academic advisor before sophomore registration saved me from delaying graduation by a full semester. I originally planned to take two heavy lab courses together while skipping an introductory statistics prerequisite, thinking I could catch up on my own. My advisor spotted the workload bottleneck immediately and suggested swapping one elective to spring. That simple fifteen-minute audit kept my grades steady and helped me qualify for summer lab research.",
            "tips": "เล่าเหตุการณ์จริงหรือสมมติที่สมจริงตามโครงสร้าง: ปัญหาเดิม -> คำแนะนำที่ได้จาก advisor -> ผลลัพธ์เชิงบวก พูดจังหวะสม่ำเสมอ ~45 วินาที"
