            "tips": "เริ่มด้วยประโยคเปรียบเทียบ ('While...') เพื่อแสดงความรอบคอบ เลือกจุดยืนที่ชัด (live events) แล้วปิดด้วยข้อเสนอแบบผสมผสานที่ทำได้จริง"
